CREATE DATABASE IF NOT EXISTS dama_game CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE dama_game;
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(40) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('player','admin') NOT NULL DEFAULT 'player', wins INT NOT NULL DEFAULT 0, losses INT NOT NULL DEFAULT 0, draws INT NOT NULL DEFAULT 0, streak INT NOT NULL DEFAULT 0, best_streak INT NOT NULL DEFAULT 0, captures INT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS games (id BIGINT AUTO_INCREMENT PRIMARY KEY, room_code VARCHAR(16) NOT NULL UNIQUE, player1_id INT NULL, player2_id INT NULL, winner_id INT NULL, status ENUM('waiting','playing','finished','draw','abandoned') NOT NULL DEFAULT 'waiting', result_reason VARCHAR(60) NULL, started_at DATETIME NULL, finished_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(player1_id) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY(player2_id) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY(winner_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS game_moves (id BIGINT AUTO_INCREMENT PRIMARY KEY, game_id BIGINT NOT NULL, user_id INT NULL, move_no INT NOT NULL, from_sq VARCHAR(4) NOT NULL, to_sq VARCHAR(4) NOT NULL, captures_json JSON NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(game_id) REFERENCES games(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS achievements (id INT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(50) UNIQUE NOT NULL, name VARCHAR(80) NOT NULL, description VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS user_achievements (user_id INT NOT NULL, achievement_id INT NOT NULL, awarded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,achievement_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(achievement_id) REFERENCES achievements(id) ON DELETE CASCADE);
INSERT IGNORE INTO achievements(code,name,description) VALUES ('FIRST_WIN','First Win','Win your first Dama game'),('TEN_WINS','Ten Wins','Win 10 games'),('STREAK_5','Hot Streak','Win 5 games in a row'),('KING_MASTER','King Master','Promote a piece to King');
